import sys

tokens = iter(sys.stdin.read().split())
def read_int():
    return int(next(tokens))

def read_word():
    return next(tokens)

n = read_int()
q = read_int()
prefix = [0] * (n + 1)
for i in range(n):
    prefix[i + 1] = prefix[i] + read_int()
result = []
for _ in range(q):
    l = read_int()
    r = read_int()
    before = max(0, l - 1)
    result.append(prefix[r + 1] - prefix[before])
print(*result)

