#include <stdio.h>
#include <string.h>

int main(void) {
    int n, k;
    scanf("%d", &n);
    scanf("%d", &k);
    int a[2000] = {0};
    int left = 0;
    int dark = 0;
    int best = 0;
    for (int right = 0; right < n; right++) {
        scanf("%d", &a[right]);
        if (a[right] == 0) {
            dark++;
        }
        while (dark > k + 1) {
            if (a[left] == 0) {
                dark--;
            }
            left++;
        }
        if (right - left + 1 > best) {
            best = right - left + 1;
        }
    }
    printf("%d ", (best));
    printf("\n");
    return 0;
}

