#include <stdio.h>
#include <string.h>

int main(void) {
    char s[257];
    char key[257];
    scanf("%256s", s);
    scanf("%256s", key);
    int need[26] = {0};
    int have[26] = {0};
    for (int i = 0; i < (int)strlen(key); i++) {
        need[key[i] - 'a']++;
    }
    int missing = (int)strlen(key);
    int left = 0;
    int best = (int)strlen(s) + 1;
    for (int right = 0; right < (int)strlen(s); right++) {
        int x = s[right] - 'a';
        if (have[x] < need[x]) {
            missing--;
        }
        have[x]++;
        while (missing == 0 && left <= right) {
            if (right - left + 1 < best) {
                best = right - left + 1;
            }
            int y = s[left] - 'a';
            have[y]--;
            if (have[y] <= need[y]) {
                missing++;
            }
            left++;
        }
    }
    if (best > (int)strlen(s)) {
        printf("%d ", (-1));
    } else {
        printf("%d ", (best));
    }
    printf("\n");
    return 0;
}

