#include <string.h>

int main(void) {
    char a[257];
    char b[257];
    scanf("%256s", a);
    scanf("%256s", b);
    int dp[201] = {0};
    for (int j = 0; j <= (int)strlen(b); j++) {
        dp[j] = j;
    }
    for (int i = 1; i <= (int)strlen(a); i++) {
        int diagonal = dp[0];
        dp[0] = i;
        for (int j = 1; j <= (int)strlen(b); j++) {
            int old = dp[j];
            int cost = 0;
            if (a[i - 1] != b[j - 1]) {
                cost = 1;
            }
            int best = diagonal + cost;
            if (old + 1 < best) {
                best = old + 1;
            }
            if (dp[j - 1] + 1 < best) {
                best = dp[j - 1] + 1;
            }
            dp[j] = best;
            diagonal = dp[j];
        }
    }
    printf("%d ", (dp[(int)strlen(b)]));
    printf("\n");
    return 0;
}

