int main(void) {
    int n;
    scanf("%d", &n);
    int a[2001] = {0};
    int stack[2001] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    int size = 0;
    int best = 0;
    for (int i = 0; i <= n; i++) {
        while (size > 0 && a[stack[size - 1]] > a[i]) {
            size--;
            int height = a[stack[size]];
            int width = i;
            if (size > 0) {
                width = i - stack[size - 1];
            }
            int area = height * width;
            if (area > best) {
                best = area;
            }
        }
        stack[size] = i;
        size++;
    }
    printf("%d ", (best));
    printf("\n");
    return 0;
}

