    int deque[2001] = {0};
    for (int i = 0; i < n; i++) {
        int value;
        scanf("%d", &value);
        prefix[i + 1] = prefix[i] + value;
    }
    int head = 0;
    int tail = 0;
    int best = n + 1;
    for (int i = 0; i <= n; i++) {
        if (head < tail && prefix[i] - prefix[deque[head]] >= target) {
            int length = i - deque[head];
            if (length < best) {
                best = length;
            }
            head++;
        }
        while (head < tail && prefix[deque[tail - 1]] >= prefix[i]) {
            tail--;
        }
        deque[tail] = i;
        tail++;
    }
    if (best > n) {
        printf("%d ", (-1));
    } else {
        printf("%d ", (best));
    }
    printf("\n");
    return 0;
}

