#include <stdio.h>
#include <string.h>

int main(void) {
    char s[257];
    scanf("%256s", s);
    int n = (int)strlen(s);
    int sa[256] = {0};
    int rank[256] = {0};
    int nextRank[256] = {0};
    for (int i = 0; i < n; i++) {
        sa[i] = i;
        rank[i] = s[i] - 'a';
    }
    for (int step = 1; step < n; step *= 2) {
        for (int i = 1; i < n; i++) {
            int key = sa[i];
            int keySecond = -1;
            if (key + step < n) {
                keySecond = rank[key + step];
            }
            int j = i - 1;
            while (j >= 0) {
                int other = sa[j];
                int otherSecond = -1;
                if (other + step < n) {
                    otherSecond = rank[other + step];
                }
                if (rank[other] < rank[key] || (rank[other] == rank[key] && otherSecond <= keySecond)) {
                    break;
                }
                sa[j + 1] = sa[j];
                j--;
            }
            sa[j + 1] = key;
        }
        nextRank[sa[0]] = 0;
        for (int i = 1; i < n; i++) {
            int previous = sa[i - 1];
            int current = sa[i];
            int a = -1;
            int b = -1;
            if (previous + step < n) {
                a = rank[previous + step];
            }
            if (current + step < n) {
                b = rank[current + step];
            }
            nextRank[current] = nextRank[previous];
            if (rank[previous] != rank[current] || a != b) {
                nextRank[current]++;
            }
        }
        for (int i = 0; i < n; i++) {
            rank[i] = nextRank[i];
        }
    }
    for (int i = 0; i < n; i++) {
        rank[sa[i]] = i;
    }
    int shared = 0;
    int height = 0;
    for (int i = 0; i < n; i++) {
        if (rank[i] == 0) {
            height = 0;
        } else {
            int j = sa[rank[i] - 1];
            while (i + height < n && j + height < n && s[i + height] == s[j + height]) {
                height++;
            }
            shared += height;
            if (height > 0) {
                height -= 0;
            }
        }
    }
    printf("%d ", (n * (n + 1) / 2 - shared));
    printf("\n");
    return 0;
}

