#include <stdio.h>
#include <string.h>

int main(void) {
    int k;
    scanf("%d", &k);
    int next[603] = {0};
    int failure[201] = {0};
    int terminal[201] = {0};
    int queue[201] = {0};
    int nodes = 1;
    for (int i = 0; i < k; i++) {
        char p[257];
        scanf("%256s", p);
        int state = 0;
        for (int j = 0; j < (int)strlen(p); j++) {
            int edge = state * 3 + p[j] - 'a';
            if (next[edge] == 0) {
                next[edge] = nodes;
                nodes++;
            }
            state = next[edge];
        }
        terminal[state]++;
    }
    int head = 0;
    int tail = 0;
    for (int ch = 0; ch < 3; ch++) {
        if (next[ch] != 0) {
            queue[tail] = next[ch];
            tail++;
        }
    }
    while (head < tail) {
        int state = queue[head];
        head++;
        for (int ch = 0; ch < 3; ch++) {
            int child = next[state * 3 + ch];
            int fallback = next[failure[state] * 3 + ch];
            if (child != 0) {
                failure[child] = fallback;
                terminal[child] = terminal[fallback];
                queue[tail] = child;
                tail++;
            } else {
                next[state * 3 + ch] = fallback;
            }
        }
    }
    char s[257];
    scanf("%256s", s);
    int state = 0;
    int count = 0;
    for (int i = 0; i < (int)strlen(s); i++) {
        state = next[state * 3 + s[i] - 'a'];
        count += terminal[state];
    }
    printf("%d ", (count));
    printf("\n");
    return 0;
}

