int main(void) {
    int n, alignment, size;
    scanf("%d", &n);
    scanf("%d", &alignment);
    scanf("%d", &size);
    int answer = -1;
    for (int i = 0; i < n; i++) {
        int left, right;
        scanf("%d", &left);
        scanf("%d", &right);
        int candidate = left;
        while (candidate % alignment != 0) {
            candidate++;
        }
        if (answer == -1 && left + size <= right) {
            answer = candidate;
        }
    }
    printf("%d ", (answer));
