#include <stdio.h>
#include <string.h>

int main(void) {
    int capacity, q;
    scanf("%d", &capacity);
    scanf("%d", &q);
    int pageAt[8] = {0};
    int stamp[8] = {0};
    int pinned[8] = {0};
    int loads = 0;
    int blocked = 0;
    for (int time = 1; time <= q; time++) {
        int op, page;
        scanf("%d", &op);
        scanf("%d", &page);
        int hit = -1;
        int empty = -1;
        for (int j = 0; j < capacity; j++) {
            if (pageAt[j] == page) {
                hit = j;
            }
            if (pageAt[j] == 0 && empty == -1) {
                empty = j;
            }
        }
        if (op != 0) {
            if (hit != -1) {
                pinned[hit] = op == 1 ? 1 : 0;
            }
        } else if (hit != -1) {
            stamp[hit] = time;
        } else {
            int victim = empty;
            if (victim == -1) {
                for (int j = 0; j < capacity; j++) {
                    if (victim == -1 || stamp[j] < stamp[victim]) {
                        victim = j;
                    }
                }
            }
            if (victim == -1) {
                blocked++;
            } else {
                pageAt[victim] = page;
                stamp[victim] = time;
                pinned[victim] = 0;
                loads++;
            }
        }
    }
    printf("%d ", (loads));
    printf("%d ", (blocked));
    for (int j = 0; j < capacity; j++) {
        printf("%d ", (pageAt[j]));
    }
    printf("\n");
    return 0;
}

