#include <string.h>

int main(void) {
    int n, head;
    scanf("%d", &n);
    scanf("%d", &head);
    int track[100] = {0};
    int done[100] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &track[i]);
    }
    int distance = 0;
    for (int step = 0; step < n; step++) {
        int chosen = -1;
        for (int i = 0; i < n; i++) {
            if (done[i] == 0 && track[i] >= head && (chosen == -1 || track[i] < track[chosen])) {
                chosen = i;
            }
        }
        int wrapped = chosen == -1 ? 1 : 0;
        if (wrapped == 1) {
            for (int i = 0; i < n; i++) {
                if (done[i] == 0 && (chosen == -1 || track[i] < track[chosen])) {
                    chosen = i;
                }
            }
        }
        int movement = track[chosen] - head;
        if (movement < 0) {
            movement = -movement;
        }
        if (wrapped == 0) {
            distance += movement;
        }
        head = track[chosen];
        done[chosen] = 1;
        printf("%d ", (head));
    }
    printf("%d ", (distance));
    printf("\n");
    return 0;
}

