    scanf("%d", &capacity);
    scanf("%d", &n);
    int pageAt[8] = {0};
    int freq[8] = {0};
    int stamp[8] = {0};
    int misses = 0;
    for (int time = 1; time <= n; time++) {
        int page;
        scanf("%d", &page);
        int hit = -1;
        int victim = -1;
        for (int j = 0; j < capacity; j++) {
            if (pageAt[j] == page) {
                hit = j;
            }
            if (pageAt[j] == 0 && victim == -1) {
                victim = j;
            }
        }
        if (hit != -1) {
            freq[hit]++;
            stamp[hit] = time;
        } else {
            misses++;
            if (victim == -1) {
                victim = 0;
                for (int j = 1; j < capacity; j++) {
                    if (freq[j] < freq[victim] || (freq[j] == freq[victim] && stamp[j] < stamp[victim])) {
                        victim = j;
                    }
                }
            }
            pageAt[victim] = page;
            freq[victim] += 1;
            stamp[victim] = time;
        }
    }
    printf("%d ", (misses));
    for (int j = 0; j < capacity; j++) {
        printf("%d ", (pageAt[j]));
    }
    printf("\n");
    return 0;
}

