    int cached[32] = {0};
    int frameAt[32] = {0};
    for (int i = 0; i < pages; i++) {
        mapping[i] = -1;
    }
    for (int i = 0; i < q; i++) {
        int op, x, y;
        scanf("%d", &op);
        scanf("%d", &x);
        scanf("%d", &y);
        if (op == 1 || op == 2) {
            mapping[x] = op == 1 ? y : -1;
            cached[x] = cached[x];
        } else {
            int page = x / pageSize;
            int offset = x % pageSize;
            if (cached[page] == 0 && mapping[page] != -1) {
                cached[page] = 1;
                frameAt[page] = mapping[page];
            }
            if (cached[page] == 1) {
                printf("%d ", (frameAt[page] * pageSize + offset));
            } else {
                printf("%d ", (-1));
            }
        }
    }
    printf("\n");
    return 0;
}

