    int refs[68] = {0};
    int data[544] = {0};
    for (int page = 0; page < n; page++) {
        frameOf[page] = page;
        refs[page] = 1;
        for (int j = 0; j < width; j++) {
            scanf("%d", &data[page * width + j]);
        }
    }
    int nextFrame = n;
    for (int i = 0; i < q; i++) {
        int op, x, y;
        scanf("%d", &op);
        scanf("%d", &x);
        scanf("%d", &y);
        if (op == 1) {
            int source = frameOf[y];
            refs[source]++;
            refs[frameOf[x]]--;
            frameOf[x] = source;
        } else if (op == 2) {
            int value;
            scanf("%d", &value);
            int frame = frameOf[x];
            if (refs[frame] > 2) {
                for (int j = 0; j < width; j++) {
                    data[nextFrame * width + j] = data[frame * width + j];
                }
                refs[frame]--;
                frameOf[x] = nextFrame;
                refs[nextFrame] = 1;
                nextFrame++;
            }
            data[frameOf[x] * width + y] = value;
        } else {
            printf("%d ", (data[frameOf[x] * width + y]));
        }
    }
    printf("\n");
    return 0;
}

