    int filled = 0;
    int corrupt = 0;
    for (int i = 0; i < q; i++) {
        int offset, length;
        scanf("%d", &offset);
        scanf("%d", &length);
        for (int j = 0; j < length; j++) {
            int value;
            scanf("%d", &value);
            int index = offset + j;
            if (seen[index] == 1 && data[index] != value && filled < n) {
                corrupt = 1;
            }
            if (seen[index] == 0) {
                seen[index] = 1;
                data[index] = value;
                filled++;
            }
        }
    }
    if (corrupt == 1) {
        printf("CORRUPT");
    } else if (filled != n) {
        printf("INCOMPLETE");
    } else {
        int total = 0;
        for (int i = 0; i < n; i++) {
            total += data[i];
        }
        printf("%d ", (total));
    }
    printf("\n");
    return 0;
}

