#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m, q;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &q);
    int roots[32] = {0};
    int refs[32] = {0};
    int alive[32] = {0};
    int from[100] = {0};
    int to[100] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &roots[i]);
        refs[i] = roots[i];
        alive[i] = 1;
    }
    for (int i = 0; i < m; i++) {
        scanf("%d", &from[i]);
        scanf("%d", &to[i]);
        refs[to[i]]++;
    }
    for (int i = 0; i < q; i++) {
        int node;
        scanf("%d", &node);
        roots[node]--;
        refs[node]--;
        while (1 == 1) {
            int dead = -1;
            for (int j = 0; j < n; j++) {
                if (alive[j] == 1 && roots[j] == 0) {
                    dead = j;
                    break;
                }
            }
            if (dead == -1) {
                break;
            }
            alive[dead] = 0;
            for (int edge = 0; edge < m; edge++) {
                if (from[edge] == dead) {
                    refs[to[edge]]--;
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        printf("%d ", (alive[i]));
    }
    printf("\n");
    return 0;
}

