#include <stdio.h>
#include <string.h>

int main(void) {
    int n, q;
    scanf("%d", &n);
    scanf("%d", &q);
    int memory[16] = {0};
    int marks[16] = {0};
    int cellAt[100] = {0};
    int before[100] = {0};
    int depth = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &memory[i]);
    }
    for (int i = 0; i < q; i++) {
        int op;
        scanf("%d", &op);
        if (op == 1) {
            marks[depth] = count;
            depth++;
        } else if (op == 2) {
            int cell, value;
            scanf("%d", &cell);
            scanf("%d", &value);
            if (depth > 0) {
                cellAt[count] = cell;
                before[count] = memory[cell];
                count++;
            }
            memory[cell] = value;
        } else if (op == 3) {
            depth--;
            if (depth >= 0) {
                count = 0;
            }
        } else if (op == 4) {
            depth--;
            while (count > marks[depth]) {
                count--;
                memory[cellAt[count]] = before[count];
            }
        } else {
            int cell;
            scanf("%d", &cell);
            printf("%d ", (memory[cell]));
        }
    }
    printf("\n");
    return 0;
}

