int main(void) {
    int n, m, r, q;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &r);
    scanf("%d", &q);
    int color[32] = {0};
    int owner[64] = {0};
    int target[64] = {0};
    for (int i = 0; i < r; i++) {
        int root;
        scanf("%d", &root);
        color[root] = 1;
    }
    for (int edge = 0; edge < m; edge++) {
        scanf("%d", &owner[edge]);
        scanf("%d", &target[edge]);
    }
    for (int event = 0; event < q; event++) {
        int op;
        scanf("%d", &op);
        if (op == 1) {
            int chosen = -1;
            for (int node = 0; node < n; node++) {
                if (color[node] == 1) {
                    chosen = node;
                    break;
                }
            }
            if (chosen != -1) {
                color[chosen] = 2;
                for (int edge = 0; edge < m; edge++) {
                    int child = target[edge];
                    if (owner[edge] == chosen && child != -1 && color[child] == 0) {
                        color[child] = 1;
                    }
                }
            }
        } else if (op == 2) {
            int edge, child;
            scanf("%d", &edge);
            scanf("%d", &child);
            target[edge] = child;
            if (color[owner[edge]] == 1 && child != -1 && color[child] == 0) {
                color[child] = 1;
            }
        } else {
            int root;
            scanf("%d", &root);
            if (color[root] == 0) {
                color[root] = 1;
            }
        }
    }
    while (1 == 1) {
        int chosen = -1;
        for (int node = 0; node < n; node++) {
            if (color[node] == 1) {
                chosen = node;
                break;
            }
        }
        if (chosen == -1) {
            break;
        }
        color[chosen] = 2;
        for (int edge = 0; edge < m; edge++) {
            int child = target[edge];
            if (owner[edge] == chosen && child != -1 && color[child] == 0) {
                color[child] = 1;
            }
        }
    }
    for (int node = 0; node < n; node++) {
        printf("%d ", (color[node] == 0 ? 0 : 1));
    }
    printf("\n");
    return 0;
}

