#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int value[32] = {0};
    int total[32] = {0};
    int parent[32] = {0};
    int queue[32] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &value[i]);
        total[i] = value[i];
    }
    for (int i = 1; i < n; i++) {
        scanf("%d", &parent[i]);
    }
    int head = 0;
    int tail = 1;
    queue[0] = 0;
    while (head < tail) {
        int u = queue[head++];
        for (int v = 1; v < n; v++) {
            if (parent[v] == u) {
                queue[tail++] = v;
            }
        }
    }
    for (int i = n - 1; i > 0; i--) {
        int u = queue[i];
        total[parent[u]] += value[u];
    }
    for (int i = 0; i < n; i++) {
        printf("%d ", (total[i]));
    }
    printf("\n");
    return 0;
}

