import sys

tokens = iter(sys.stdin.read().split())
def read_int():
    return int(next(tokens))

def read_word():
    return next(tokens)

n = read_int()
value = [read_int() for _ in range(n)]
parent = [0] + [read_int() for _ in range(n - 1)]
total = list(value)
queue = [0]
head = 0
while head < len(queue):
    u = queue[head]
    head += 1
    for v in range(1, n):
        if parent[v] == u:
            queue.append(v)
for u in reversed(queue[1:]):
    total[parent[u]] += value[u]
print(*total)

