#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m;
    scanf("%d", &n);
    scanf("%d", &m);
    int edge[1024] = {0};
    int degree[32] = {0};
    int queue[32] = {0};
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d", &u);
        scanf("%d", &v);
        edge[u * 32 + v] = 1;
        edge[v * 32 + u] = 1;
        degree[u]++;
        degree[v]++;
    }
    int head = 0;
    int tail = 0;
    for (int v = 0; v < n; v++) {
        if (degree[v] <= 1) {
            queue[tail++] = v;
        }
    }
    int remaining = n;
    while (remaining > 2) {
        int batch = 1;
        remaining -= batch;
        for (int i = 0; i < batch; i++) {
            int u = queue[head++];
            for (int v = 0; v < n; v++) {
                if (edge[u * 32 + v] != 0) {
                    degree[v]--;
                    if (degree[v] == 1) {
                        queue[tail++] = v;
                    }
                }
            }
        }
    }
    for (int v = 0; v < n; v++) {
        for (int i = head; i < tail; i++) {
            if (queue[i] == v) {
                printf("%d ", (v));
            }
        }
    }
    printf("\n");
    return 0;
}

