#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m, s;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &s);
    int edge[1024] = {0};
    int distance[32] = {0};
    int done[32] = {0};
    for (int i = 0; i < 1024; i++) {
        edge[i] = -1;
    }
    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d", &u);
        scanf("%d", &v);
        scanf("%d", &w);
        edge[u * 32 + v] = w;
    }
    for (int i = 0; i < n; i++) {
        distance[i] = 1000000;
    }
    distance[s] = 0;
    for (int step = 0; step < n; step++) {
        int u = -1;
        for (int v = 0; v < n; v++) {
            if (done[v] == 0 && (u == -1 || v < u)) {
                u = v;
            }
        }
        if (u == -1 || distance[u] == 1000000) {
            break;
        }
        done[u] = 1;
        for (int v = 0; v < n; v++) {
            int weight = edge[u * 32 + v];
            if (weight >= 0 && done[v] == 0) {
                int candidate = distance[u] + weight;
                if (candidate < distance[v]) {
                    distance[v] = candidate;
                }
            }
        }
    }
    for (int v = 0; v < n; v++) {
        printf("%d ", (distance[v] == 1000000 ? -1 : distance[v]));
    }
    printf("\n");
    return 0;
}

