#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m, s;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &s);
    int edge[1024] = {0};
    int distance[32] = {0};
    int done[32] = {0};
    int queue[512] = {0};
    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d", &u);
        scanf("%d", &v);
        scanf("%d", &w);
        edge[u * 32 + v] = w + 1;
    }
    for (int v = 0; v < n; v++) {
        distance[v] = 1000000;
    }
    int head = 256;
    int tail = 256;
    distance[s] = 0;
    queue[tail++] = s;
    while (head < tail) {
        int u = queue[head++];
        if (done[u] != 0) {
            continue;
        }
        done[u] = 1;
        for (int v = 0; v < n; v++) {
            if (edge[u * 32 + v] != 0 && done[v] == 0) {
                int weight = edge[u * 32 + v] - 1;
                int candidate = distance[u] + weight;
                if (candidate < distance[v]) {
                    distance[v] = candidate;
                    if (weight == 1) {
                        queue[--head] = v;
                    } else {
                        queue[tail++] = v;
                    }
                }
            }
        }
    }
    for (int v = 0; v < n; v++) {
        printf("%d ", (distance[v] == 1000000 ? -1 : distance[v]));
    }
    printf("\n");
    return 0;
}

