public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n, m, s;
        n = scanner.nextInt();
        m = scanner.nextInt();
        s = scanner.nextInt();
        int[] edge = new int[1024];
        int[] distance = new int[32];
        int[] done = new int[32];
        for (int i = 0; i < 1024; i++) {
            edge[i] = -1;
        }
        for (int i = 0; i < m; i++) {
            int u, v, w;
            u = scanner.nextInt();
            v = scanner.nextInt();
            w = scanner.nextInt();
            edge[u * 32 + v] = w;
        }
        for (int v = 0; v < n; v++) {
            distance[v] = 1000000;
        }
        distance[s] = 0;
        for (int step = 0; step < n; step++) {
            int u = -1;
            for (int v = 0; v < n; v++) {
                if (done[v] == 0 && (u == -1 || distance[v] < distance[u])) {
                    u = v;
                }
            }
            if (u == -1 || distance[u] == 1000000) {
                break;
            }
            done[u] = 1;
            for (int v = 0; v < n; v++) {
                int weight = edge[u * 32 + v];
                if (weight >= 0 && done[v] == 0) {
                    int candidate = distance[u];
                    if (weight > candidate) {
                        candidate += weight;
                    }
                    if (candidate < distance[v]) {
                        distance[v] = candidate;
                    }
                }
            }
        }
        for (int v = 0; v < n; v++) {
            System.out.print((distance[v] == 1000000 ? -1 : distance[v]) + " ");
        }
        System.out.println();
    }
}

