#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m, s;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &s);
    int from[160] = {0};
    int to[160] = {0};
    int weight[160] = {0};
    int distance[32] = {0};
    for (int i = 0; i < m; i++) {
        scanf("%d", &from[i]);
        scanf("%d", &to[i]);
        scanf("%d", &weight[i]);
    }
    for (int v = 0; v < n; v++) {
        distance[v] = 1000000;
    }
    distance[s] = 0;
    for (int pass = 0; pass < n - 1; pass++) {
        for (int i = 0; i < m; i++) {
            int u = from[i];
            int v = to[i];
            if (distance[u] != 1000000 && distance[u] + weight[i] < distance[v]) {
                distance[v] = distance[u] + weight[i];
            }
        }
    }
    int alarm = 0;
    for (int i = 0; i < m; i++) {
        int u = from[i];
        int v = to[i];
        if (distance[u] + weight[i] < distance[v]) {
            alarm = 1;
        }
    }
    printf("%d ", (alarm));
    printf("\n");
    return 0;
}

