#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m;
    scanf("%d", &n);
    scanf("%d", &m);
    int edge[1024] = {0};
    int key[32] = {0};
    int done[32] = {0};
    for (int i = 0; i < 1024; i++) {
        edge[i] = -1;
    }
    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d", &u);
        scanf("%d", &v);
        scanf("%d", &w);
        edge[u * 32 + v] = w;
        edge[v * 32 + u] = w;
    }
    for (int v = 0; v < n; v++) {
        key[v] = 1000000;
    }
    key[0] = 0;
    int total = 0;
    int connected = 1;
    for (int step = 0; step < n; step++) {
        int u = -1;
        for (int v = 0; v < n; v++) {
            if (done[v] == 0 && (u == -1 || key[v] < key[u])) {
                u = v;
            }
        }
        if (key[u] == 1000000) {
            connected = 0;
            break;
        }
        done[u] = 1;
        total += key[u];
        for (int v = 0; v < n; v++) {
            int weight = edge[u * 32 + v];
            if (weight >= 0 && done[v] == 0 && weight < key[v]) {
                key[v] = key[u] + weight;
            }
        }
    }
    printf("%d ", (connected != 0 ? total : -1));
    printf("\n");
    return 0;
}

