    int n, m;
    scanf("%d", &n);
    scanf("%d", &m);
    int edge[1024] = {0};
    int reach[1024] = {0};
    int component[32] = {0};
    int size[32] = {0};
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d", &u);
        scanf("%d", &v);
        edge[u * 32 + v] = 1;
        reach[u * 32 + v] = 1;
    }
    for (int v = 0; v < n; v++) {
        reach[v * 32 + v] = 1;
        component[v] = -1;
    }
    for (int k = 0; k < n; k++) {
        for (int u = 0; u < n; u++) {
            for (int v = 0; v < n; v++) {
                if (reach[u * 32 + k] != 0 && reach[k * 32 + v] != 0) {
                    reach[u * 32 + v] = 1;
                }
            }
        }
    }
    int groups = 0;
    for (int u = 0; u < n; u++) {
        if (component[u] == -1) {
            for (int v = 0; v < n; v++) {
                if (reach[u * 32 + v] != 0 || reach[v * 32 + u] != 0) {
                    component[v] = groups;
                    size[groups]++;
                }
            }
            groups++;
        }
    }

    int incoming[32] = {0};
    for (int u = 0; u < n; u++) {
        for (int v = 0; v < n; v++) {
            if (edge[u * 32 + v] != 0 && component[u] != component[v]) {
                incoming[component[v]] = 1;
            }
        }
    }
    int answer = 0;
    for (int i = 0; i < groups; i++) {
        if (incoming[i] == 0) {
            answer++;
        }
    }
    printf("%d ", (answer));
    printf("\n");
    return 0;
}

