    int size[32] = {0};
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d", &u);
        scanf("%d", &v);
        edge[u * 32 + v] = 1;
        reach[u * 32 + v] = 1;
    }
    for (int v = 0; v < n; v++) {
        reach[v * 32 + v] = 1;
        component[v] = -1;
    }
    for (int k = 0; k < n; k++) {
        for (int u = 0; u < n; u++) {
            for (int v = 0; v < n; v++) {
                if (reach[u * 32 + k] != 0 && reach[k * 32 + v] != 0) {
                    reach[u * 32 + v] = 1;
                }
            }
        }
    }
    int groups = 0;
    for (int u = 0; u < n; u++) {
        if (component[u] == -1) {
            for (int v = 0; v < n; v++) {
                if (reach[u * 32 + v] != 0 && reach[v * 32 + u] != 0) {
                    component[v] = groups;
                    size[groups]++;
                }
            }
            groups++;
        }
    }

    int dag[1024] = {0};
    int indegree[32] = {0};
    int best[32] = {0};
    int queue[32] = {0};
    for (int u = 0; u < n; u++) {
        for (int v = 0; v < n; v++) {
            int a = component[u];
            int b = component[v];
            if (edge[u * 32 + v] != 0 && a != b && dag[a * 32 + b] == 0) {
                dag[a * 32 + b] = 1;
                indegree[b]++;
            }
        }
    }
    int head = 0;
    int tail = 0;
    for (int i = 0; i < groups; i++) {
        best[i] = size[i];
        if (indegree[i] == 0) {
            queue[tail++] = i;
        }
    }
    int answer = 0;
    while (head < tail) {
        int u = queue[head++];
        if (best[u] > answer) {
            answer = best[u];
        }
        for (int v = 0; v < groups; v++) {
            if (dag[u * 32 + v] != 0) {
                int candidate = best[u] + 1;
                if (candidate > best[v]) {
                    best[v] = candidate;
                }
                indegree[v]--;
                if (indegree[v] == 0) {
                    queue[tail++] = v;
                }
            }
        }
    }
    printf("%d ", (answer));
    printf("\n");
    return 0;
}

