    int n, q;
    scanf("%d", &n);
    scanf("%d", &q);
    int up[192] = {0};
    int depth[32] = {0};
    int power[6] = {0};
    power[0] = 1;
    for (int k = 1; k < 6; k++) {
        power[k] = power[k - 1] * 2;
    }
    for (int v = 1; v < n; v++) {
        scanf("%d", &up[v]);
        depth[v] = depth[up[v]] + 1;
    }
    for (int k = 1; k < 6; k++) {
        for (int v = 0; v < n; v++) {
            up[k * 32 + v] = up[(k - 1) * 32 + v];
        }
    }
    for (int query = 0; query < q; query++) {
        int a, b;
        scanf("%d", &a);
        scanf("%d", &b);
        if (depth[a] < depth[b]) {
            int saved = a;
            a = b;
            b = saved;
        }
        int difference = depth[a] - depth[b];
        for (int k = 0; k < 6; k++) {
            if ((difference / power[k]) % 2 == 1) {
                a = up[k * 32 + a];
            }
        }
        if (a != b) {
            for (int k = 5; k >= 0; k--) {
                if (up[k * 32 + a] != up[k * 32 + b]) {
                    a = up[k * 32 + a];
                    b = up[k * 32 + b];
                }
            }
            a = up[a];
        }
        printf("%d ", (a));
    }
    printf("\n");
    return 0;
}

