#include <stdio.h>
#include <string.h>

int main(void) {
    int n, q;
    scanf("%d", &n);
    scanf("%d", &q);
    int subtree[32] = {0};
    int parent[32] = {0};
    for (int v = 0; v < n; v++) {
        scanf("%d", &subtree[v]);
    }
    for (int v = 1; v < n; v++) {
        scanf("%d", &parent[v]);
    }
    for (int v = n - 1; v > 0; v--) {
        subtree[parent[v]] += subtree[v];
    }
    int total = subtree[0];
    for (int query = 0; query < q; query++) {
        int r, x;
        scanf("%d", &r);
        scanf("%d", &x);
        int answer;
        if (r == x) {
            answer = total;
        } else {
            int u = r;
            while (u != 0 && u != x) {
                u = parent[u];
            }
            if (u != x) {
                answer = subtree[x];
            } else {
                int child = r;
                while (parent[child] != x) {
                    child = parent[child];
                }
                answer = total - subtree[x];
            }
        }
        printf("%d ", (answer));
    }
    printf("\n");
    return 0;
}

