        }
        for (int v = 1; v < n; v++) {
            parent[v] = scanner.nextInt();
        }
        for (int v = n - 1; v > 0; v--) {
            subtree[parent[v]] += subtree[v];
        }
        int total = subtree[0];
        for (int query = 0; query < q; query++) {
            int r, x;
            r = scanner.nextInt();
            x = scanner.nextInt();
            int answer;
            if (r == x) {
                answer = total;
            } else {
                int u = r;
                while (u != 0 && u != x) {
                    u = parent[u];
                }
                if (u != x) {
                    answer = subtree[x];
                } else {
                    int child = r;
                    while (parent[child] != x) {
                        child = parent[child];
                    }
                    answer = total - subtree[child];
                }
            }
            System.out.print((answer) + " ");
        }
        System.out.println();
    }
}

