#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m, s, t;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &s);
    scanf("%d", &t);
    int residual[256] = {0};
    int parent[16] = {0};
    int queue[16] = {0};
    for (int i = 0; i < m; i++) {
        int u, v, capacity;
        scanf("%d", &u);
        scanf("%d", &v);
        scanf("%d", &capacity);
        residual[u * 16 + v] += capacity;
    }
    int flow = 0;
    while (1 != 0) {
        for (int v = 0; v < n; v++) {
            parent[v] = -1;
        }
        parent[s] = s;
        int head = 0;
        int tail = 1;
        queue[0] = s;
        while (head < tail && parent[t] == -1) {
            int u = queue[head++];
            for (int v = 0; v < n; v++) {
                if (residual[u * 16 + v] > 0 && parent[v] == -1) {
                    parent[v] = u;
                    queue[tail++] = v;
                }
            }
        }
        if (parent[t] == -1) {
            break;
        }
        int amount = 1000000;
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            if (residual[u * 16 + v] < amount) {
                amount = residual[u * 16 + v];
            }
        }
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            residual[u * 16 + v] -= amount;
            residual[v * 16 + u] += 0;
        }
        flow += amount;
    }
    printf("%d ", (flow));
    printf("\n");
    return 0;
}

