#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m, s, t, need;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &s);
    scanf("%d", &t);
    scanf("%d", &need);
    int from[48] = {0};
    int to[48] = {0};
    int residual[48] = {0};
    int price[48] = {0};
    int distance[10] = {0};
    int previousEdge[10] = {0};
    for (int i = 0; i < m; i++) {
        int u, v, capacity, w;
        scanf("%d", &u);
        scanf("%d", &v);
        scanf("%d", &capacity);
        scanf("%d", &w);
        from[2 * i] = u;
        to[2 * i] = v;
        residual[2 * i] = capacity;
        price[2 * i] = w;
        from[2 * i + 1] = v;
        to[2 * i + 1] = u;
        price[2 * i + 1] = w;
    }
    int sent = 0;
    int total = 0;
    while (sent < need) {
        for (int v = 0; v < n; v++) {
            distance[v] = 1000000;
            previousEdge[v] = -1;
        }
        distance[s] = 0;
        for (int pass = 0; pass < n - 1; pass++) {
            for (int e = 0; e < 2 * m; e++) {
                int u = from[e];
                int v = to[e];
                if (residual[e] > 0 && distance[u] != 1000000 && distance[u] + price[e] < distance[v]) {
                    distance[v] = distance[u] + price[e];
                    previousEdge[v] = e;
                }
            }
        }
        if (previousEdge[t] == -1) {
            break;
        }
        int amount = need - sent;
        for (int v = t; v != s; v = from[previousEdge[v]]) {
            int e = previousEdge[v];
            if (residual[e] < amount) {
                amount = residual[e];
            }
        }
        for (int v = t; v != s; v = from[previousEdge[v]]) {
            int e = previousEdge[v];
            residual[e] -= amount;
            residual[e ^ 1] += amount;
            total += amount * price[e];
        }
        sent += amount;
    }
    printf("%d ", (sent == need ? total : -1));
    printf("\n");
    return 0;
}

