#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int a[16] = {0};
    int b[16] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &b[i]);
    }
    int less = 0, greater = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] < b[i]) {
            less++;
        }
        if (a[i] > b[i]) {
            greater++;
        }
    }
    if (less > 0) {
        printf("BEFORE");
    } else if (greater > 0 && less == 0) {
        printf("AFTER");
    } else if (less == 0 && greater == 0) {
        printf("EQUAL");
    } else {
        printf("CONCURRENT");
    }
    printf("\n");
    return 0;
}

