#include <string.h>

int main(void) {
    int n, m;
    scanf("%d", &n);
    scanf("%d", &m);
    int work[4] = {0};
    int allocation[28] = {0};
    int maximum[28] = {0};
    int done[7] = {0};
    for (int j = 0; j < m; j++) {
        scanf("%d", &work[j]);
    }
    for (int i = 0; i < n * m; i++) {
        scanf("%d", &allocation[i]);
    }
    for (int i = 0; i < n * m; i++) {
        scanf("%d", &maximum[i]);
    }
    int finished = 0;
    for (int pass = 0; pass < n; pass++) {
        for (int i = 0; i < n; i++) {
            int possible = 1;
            for (int j = 0; j < m; j++) {
                if (maximum[i * m + j] - allocation[i * m + j] > work[j]) {
                    possible = 0;
                }
            }
            if (done[i] == 0 && possible == 1) {
                done[i] = 1;
                finished++;
                for (int j = 0; j < m; j++) {
                    work[j] += maximum[i * m + j] - allocation[i * m + j];
                }
            }
        }
    }
    if (finished == n) {
        printf("SAFE");
    } else {
        printf("UNSAFE");
    }
    printf("\n");
    return 0;
}

