#include <stdio.h>
#include <string.h>

int main(void) {
    char word[257];
    scanf("%256s", word);
    int last[26] = {0};
    long long ways[61] = {0};
    ways[0] = 1;
    for (int i = 1; i <= (int)strlen(word); i++) {
        int ch = word[i - 1] - 'a';
        long long value = 2 * ways[i - 1];
        if (last[ch] > 0) {
            value -= ways[last[ch]];
        }
        ways[i] = (value + 1000000007LL) % 1000000007LL;
        last[ch] = i;
    }
    printf("%lld ", (long long)(ways[(int)strlen(word)]));
    printf("\n");
    return 0;
}

