    int current[8] = {0};
    int version[8] = {0};
    int saved[64] = {0};
    int savedVersion[64] = {0};
    int dirty[64] = {0};
    int touched[64] = {0};
    for (int j = 0; j < m; j++) {
        scanf("%d", &current[j]);
    }
    for (int i = 0; i < q; i++) {
        int op, t, cell, value;
        scanf("%d", &op);
        scanf("%d", &t);
        scanf("%d", &cell);
        scanf("%d", &value);
        int key = t * m + cell;
        if (op == 0) {
            for (int j = 0; j < m; j++) {
                int k = t * m + j;
                saved[k] = current[j];
                savedVersion[k] = version[j];
                dirty[k] = 0;
                touched[k] = 0;
            }
        } else if (op == 1) {
            saved[key] = value;
            dirty[key] = 1;
            touched[key] = 1;
        } else if (op == 2) {
            touched[key] = 1;
            printf("%d ", (saved[key]));
        } else {
            int valid = 1;
            for (int j = 0; j < m; j++) {
                if (dirty[t * m + j] == 1 && version[j] != savedVersion[t * m + j]) {
                    valid = 0;
                }
            }
            printf("%d ", (valid));
            if (valid == 1) {
                for (int j = 0; j < m; j++) {
                    if (dirty[t * m + j] == 1) {
                        current[j] = saved[t * m + j];
                        version[j]++;
                    }
                }
            }
        }
    }
    for (int j = 0; j < m; j++) {
        printf("%d ", (current[j]));
    }
    printf("\n");
    return 0;
}

