#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int cost[144] = {0};
    int best[4096] = {0};
    for (int i = 0; i < n * n; i++) {
        scanf("%d", &cost[i]);
    }
    int limit = 1 << n;
    for (int mask = 1; mask < limit; mask++) {
        best[mask] = 100000000;
    }
    for (int mask = 0; mask < limit; mask++) {
        int worker = 0, bits = mask;
        while (bits > 0) {
            worker += bits & 1;
            bits >>= 1;
        }
        for (int job = 0; job < n; job++) {
            if ((mask & (1 << job)) == 0) {
                int next = mask | (1 << job);
                int candidate = best[mask] + cost[(mask % n) * n + job];
                if (candidate < best[next]) {
                    best[next] = candidate;
                }
            }
        }
    }
    printf("%d ", (best[limit - 1]));
    printf("\n");
    return 0;
}

