#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int start[12] = {0};
    int end[12] = {0};
    int delta[12] = {0};
    int old[12] = {0};
    int required[12] = {0};
    int total[4096] = {0};
    int reachable[4096] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &start[i]);
        scanf("%d", &end[i]);
        scanf("%d", &delta[i]);
        scanf("%d", &old[i]);
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (end[j] <= start[i]) {
                required[i] |= 1 << j;
            }
        }
    }
    int limit = 1 << n;
    for (int mask = 1; mask < limit; mask++) {
        int bit = mask & -mask;
        int index = 0, value = bit;
        while (value > 1) {
            value >>= 1;
            index++;
        }
        total[mask] = total[mask ^ bit] + delta[index];
    }
    reachable[0] = 1;
    for (int mask = 0; mask < limit; mask++) {
        if (reachable[mask] == 1) {
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0 && total[mask] == old[i] && ((mask & required[i]) != 0 || required[i] == 0)) {
                    reachable[mask | (1 << i)] = 1;
                }
            }
        }
    }
    if (reachable[limit - 1] == 1) {
        printf("YES");
    } else {
        printf("NO");
    }
    printf("\n");
    return 0;
}

