int main(void) {
    int length[3] = {0};
    int actions[30] = {0};
    int held[33] = {0};
    int ways[1331] = {0};
    for (int t = 0; t < 3; t++) {
        scanf("%d", &length[t]);
    }
    for (int t = 0; t < 3; t++) {
        for (int p = 0; p < length[t]; p++) {
            int action;
            scanf("%d", &action);
            actions[t * 10 + p] = action;
            int lock = action;
            if (lock < 0) {
                lock = -lock;
            }
            int bit = 1 << (lock - 1);
            held[t * 11 + p + 1] = held[t * 11 + p];
            if (action > 0) {
                held[t * 11 + p + 1] |= bit;
            } else {
                held[t * 11 + p + 1] &= 3 ^ bit;
            }
        }
    }
    ways[0] = 1;
    for (int a = 0; a <= length[0]; a++) {
        for (int b = 0; b <= length[1]; b++) {
            for (int c = 0; c <= length[2]; c++) {
                int state = a * 121 + b * 11 + c;
                int busy = held[a] | held[11 + b] | held[22 + c];
                for (int t = 0; t < 3; t++) {
                    int position = a, step = 121;
                    if (t == 1) {
                        position = b;
                        step = 11;
                    } else if (t == 2) {
                        position = c;
                        step = 1;
                    }
                    if (position < length[t]) {
                        int action = actions[t * 10 + position];
                        int lock = action;
                        if (lock < 0) {
                            lock = -lock;
                        }
                        int bit = 1 << (lock - 1);
                        if (action < 0 || (held[t * 11 + position] & bit) == 0) {
                            ways[state + step] = (ways[state + step] + ways[state]) % 1000000007;
                        }
                    }
                }
            }
        }
    }
    printf("%d ", (ways[length[0] * 121 + length[1] * 11 + length[2]]));
    printf("\n");
    return 0;
}

