#include <stdio.h>
#include <string.h>

int main(void) {
    int n, m, pairs;
    scanf("%d", &n);
    scanf("%d", &m);
    scanf("%d", &pairs);
    int cover[16] = {0};
    int cost[16] = {0};
    int conflict[16] = {0};
    int valid[65536] = {0};
    int coverage[65536] = {0};
    int total[65536] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &cover[i]);
        scanf("%d", &cost[i]);
    }
    for (int i = 0; i < pairs; i++) {
        int a, b;
        scanf("%d", &a);
        scanf("%d", &b);
        conflict[a] |= 1 << b;
        conflict[b] |= 1 << a;
    }
    int limit = 1 << n;
    int full = (1 << m) - 1;
    int best = 1000000, ways = 0;
    valid[0] = 1;
    for (int mask = 1; mask < limit; mask++) {
        int bit = mask & -mask;
        int index = 0, bits = bit;
        while (bits > 1) {
            bits >>= 1;
            index++;
        }
        int previous = mask ^ bit;
        if (valid[previous] == 1 && (conflict[index] & previous) == 0 && (coverage[previous] & cover[index]) != cover[index]) {
            valid[mask] = 1;
            coverage[mask] = coverage[previous] | cover[index];
            total[mask] = total[previous] + cost[index];
            if (coverage[mask] == full) {
                if (total[mask] < best) {
                    best = total[mask];
                    ways = 1;
                } else if (total[mask] == best) {
                    ways++;
                }
            }
        }
    }
    if (ways == 0) {
        printf("%d ", (-1));
        printf("%d ", (0));
    } else {
        printf("%d ", (best));
        printf("%d ", (ways));
    }
    printf("\n");
    return 0;
}

